// 合法的 false 输入仍然产生缺陷报告（回归保护）。
func TestCLIAuditExplicitFalseStillReportsDefect(t *testing.T) {
	bin := auditBinary(t)
	work := t.TempDir()
	input := writeInput(t, work, "in.json", validInvariantInput)
