// wireInput is the JSON object accepted by the audit command.
type wireInput struct {
	Artifact   json.RawMessage            `json:"artifact"`
	Rules      json.RawMessage            `json:"rules"`
	Invariants map[string]json.RawMessage `json:"invariants"`
	Checks     json.RawMessage            `json:"checks"`
}

// Fixed submission field spellings. A submission is decoded through these exact
// names only, mirroring strictReportJSON on the read side: encoding/json
// otherwise falls back to case-insensitive matching, so an extension member
// such as "StAtus" would silently decode into the status field and could
// override — or launder — the conclusion carried by the formal "status"
// member, depending on member order. Case variants, whitespace-padded names
// and unknown members are extension data and never reach the decoder.
// Invariant names are not listed: they are user-defined, so "Inv" and "inv"
// stay two independent invariants and a padded name is not trimmed.
var (
	submissionTopKeys = []string{"artifact", "rules", "invariants", "checks"}
	submissionRuleKeys = []string{"id", "kind", "severity", "invariant", "requiresABI", "version"}
	submissionCheckKeys = []string{"artifactHash", "ruleId", "version", "status", "note"}
)

// checkStatusEntry pairs one check record's raw fixed fields with the rule id
// the record names, so a formal-status problem can identify its rule.
type checkStatusEntry struct {
	raw  json.RawMessage
	rule string
}

// ParseAuditInput decodes an audit submission JSON object into domain values.
// Invariant values must be JSON booleans; any other type is an error. Any JSON
// object in the submission that repeats a member name rejects the whole
// submission: the decoder keeps only the last value silently, so a repeated
// invariant key would choose a conclusion by member order instead of giving
// one trustworthy result. Only the fixed fields under their agreed spelling
// participate: case variants and whitespace-padded names are extension data
// and are ignored, so they can neither override a formal value nor supply one
// when the formal member is missing or invalid. Invariant names are not fixed
// fields — they are user-defined, compared case sensitively and never trimmed.
func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
	if dup := findDuplicateJSONMember(data); dup != nil {
		return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
	}
	var top wireInput
	if err := json.Unmarshal(data, &top); err != nil {
		return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
	}

	// Extract the fixed members of each nested object explicitly. A first
	// map[string]json.RawMessage pass keys by exact decoded name, so case
	// variants and padded names never alias a fixed field.
	var in wireArtifact
	if len(top.Artifact) > 0 && string(top.Artifact) != "null" {
		fields, err := fixedSubmissionFields(top.Artifact, artifactWireKeys, nil)
		if err != nil {
			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON in artifact: " + err.Error())
		}
		if err := json.Unmarshal(fields, &in); err != nil {
			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON in artifact: " + err.Error())
		}
	}

	var wireRules []wireRule
	if len(top.Rules) > 0 && string(top.Rules) != "null" {
		raw, err := fixedFieldsInArray(top.Rules, submissionRuleKeys)
		if err != nil {
			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON in rules: " + err.Error())
		}
		if err := json.Unmarshal(raw, &wireRules); err != nil {
			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON in rules: " + err.Error())
		}
	}

	// Each check record is kept apart until its formal status has been
	// validated: an absent status, a non-string status or an unsupported
	// status rejects the whole submission even when an adjacent "StAtus"
	// extension member happens to carry a legal-looking value.
	var checkEntries []checkStatusEntry
	if len(top.Checks) > 0 && string(top.Checks) != "null" {
		objects, err := rawObjectArray(top.Checks)
		if err != nil {
			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON in checks: " + err.Error())
		}
		checkEntries = make([]checkStatusEntry, 0, len(objects))
		for _, obj := range objects {
			fields, err := fixedSubmissionFields(obj, submissionCheckKeys, nil)
			if err != nil {
				return Artifact{}, nil, nil, nil, errInvalid("invalid JSON in checks: " + err.Error())
			}
			var head struct {
				RuleID string `json:"ruleId"`
			}
			_ = json.Unmarshal(fields, &head)
			if err := validateCheckStatusField(fields, head.RuleID); err != nil {
				return Artifact{}, nil, nil, nil, err
			}
			checkEntries = append(checkEntries, {raw: fields, rule: head.RuleID})
		}
	}

	invariants := make(map[string]bool, len(top.Invariants))
	for key, raw := range top.Invariants {
		// Only JSON true/false is a conclusion. Unmarshalling directly into a
		// bool would turn null into the zero value false, which would falsely
		// record a defect; require the token to be a boolean instead.
		var token any
		if err := json.Unmarshal(raw, &token); err != nil {
			return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
		}
		holds, ok := token.(bool)
		if !ok {
			return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
		}
		invariants[key] = holds
	}
	artifact := Artifact{
		Name:     in.Name,
		ABI:      in.ABI,
		Bytecode: in.Bytecode,
		Source:   in.Source,
	}
	rules := make([]Rule, 0, len(wireRules))
	for _, wr := range wireRules {
		rules = append(rules, Rule{
			ID:          wr.ID,
			Kind:        wr.Kind,
			Severity:    wr.Severity,
			Invariant:   wr.Invariant,
			RequiresABI: wr.RequiresABI,
			Version:     wr.Version,
		})
	}
	checks := make([]CheckRecord, 0, len(checkEntries))
	for _, entry := range checkEntries {
		var wc wireCheck
		if err := json.Unmarshal(entry.raw, &wc); err != nil {
			return Artifact{}, nil, nil, nil, errInvalid("check for rule " + entry.rule + ": " + err.Error())
		}
		checks = append(checks, CheckRecord{
			ArtifactHash: wc.ArtifactHash,
			RuleID:       wc.RuleID,
			Version:      wc.Version,
			Status:       wc.Status,
			Note:         wc.Note,
		})
	}
	return artifact, rules, invariants, checks, nil
}

// artifactWireKeys are the fixed spellings inside the artifact object.
var artifactWireKeys = []string{"name", "abi", "bytecode", "source"}

// rawObjectArray decodes a JSON array of raw object values, rejecting null or
// non-object elements with a type error.
func rawObjectArray(raw json.RawMessage) ([]json.RawMessage, error) {
	var elems []json.RawMessage
	if err := json.Unmarshal(raw, &elems); err != nil {
		return nil, err
	}
	out := make([]json.RawMessage, 0, len(elems))
	for _, e := range elems {
		var probe map[string]json.RawMessage
		if err := json.Unmarshal(e, &probe); err != nil {
			return nil, err
		}
		out = append(out, e)
	}
	return out, nil
}

// fixedSubmissionFields rewrites one JSON object keeping only the named
// members under their exact spelling. required names, when non-nil, must be
// present with a JSON-string value; this is only used where a missing fixed
// field must be reported at parse time. Names are compared after JSON string
// decoding, so a member name written with escapes still denotes its fixed
// field. Exact duplicates were already rejected by findDuplicateJSONMember.
func fixedSubmissionFields(raw json.RawMessage, keys []string, required map[string]bool) (json.RawMessage, error) {
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(raw, &obj); err != nil {
		return nil, err
	}
	out := make(map[string]json.RawMessage, len(keys))
	for _, k := range keys {
		if v, ok := obj[k]; ok {
			out[k] = v
		}
	}
	return json.Marshal(out)
}

// validateCheckStatusField enforces the formal status member of one check
// record: it must exist, be a JSON string, and name one of the supported
// conclusions. A missing or invalid formal status is the record's own
// problem even if an adjacent case-variant extension member carries a legal
// value — extension members never substitute for a fixed field.
func validateCheckStatusField(fields json.RawMessage, ruleID string) error {
	where := "check record"
	if ruleID != "" {
		where = "check for rule " + ruleID
	}
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(fields, &obj); err != nil {
		return errInvalid(where + ": invalid JSON")
	}
	raw, ok := obj["status"]
	if !ok {
		return errInvalid(where + ": status is required")
	}
	var status string
	if err := json.Unmarshal(raw, &status); err != nil {
		return errInvalid(where + ": status must be a string")
	}
	if !validCheckStatus(status) {
		return errInvalid(where + ": unknown status " + status)
	}
	return nil
}

