package contractsentinel

import (
	"encoding/json"
	"fmt"
	"testing"
)

func TestProbeVariants(t *testing.T) {
	// Compute correct artifact hash for a check record.
	a := Artifact{Name: "Vault", ABI: "abi", Bytecode: "0x1", Source: "Vault.sol"}
	hash := ArtifactHash(a)
	rules := `[{"id":"r1","kind":"static","severity":"high","invariant":"inv","version":"1.0.0"}]`
	artifact := `{"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"}`

	mk := func(checkBody string) string {
		b, _ := json.Marshal(struct {
			Artifact string `json:"artifact"`
			Rules    string `json:"rules"`
			Checks   string `json:"checks"`
		}{artifact, rules, "[" + checkBody + "]"})
		// string values are JSON-quoted above which is wrong for nested; build raw instead.
		_ = b
		return `{"artifact":` + artifact + `,"rules":` + rules + `,"checks":[` + checkBody + `]`
	}
	base := func(extra string) string {
		return mk(`{"artifactHash":"` + hash + `","ruleId":"r1","version":"1.0.0",` + extra + `,"note":"counterexample x"}`)
	}

	cases := map[string]string{
		"variant after defect":  base(`"status":"发现缺陷","StAtus":"通过"`),
		"variant before defect": base(`"StAtus":"通过","status":"发现缺陷"`),
		"missing formal status": base(`"StAtus":"通过"`),
		"bogus formal status":   base(`"status":"bogus","StAtus":"通过"`),
		"number formal status":  base(`"status":123,"StAtus":"通过"`),
		"padded name":           base(`" status ":"通过"`),
		"top RULES variant":     `{"artifact":` + artifact + `,"RULES":` + rules + `}`,
		"rule Version variant":  `{"artifact":` + artifact + `,"rules":[{"id":"r1","kind":"static","severity":"high","invariant":"inv","Version":"9.9.9","version":"1.0.0"}],"invariants":{"inv":false}}`,
	}
	for name, in := range cases {
		art, rs, inv, checks, err := ParseAuditInput([]byte(in))
		if err != nil {
			fmt.Printf("[%s] ERR: %v\n", name, err)
			continue
		}
		rep, berr := BuildReport(art, rs, inv, checks)
		fmt.Printf("[%s] parseOK buildErr=%v rules=%d checks=%+v findings=%d\n", name, berr, len(rs), checks, len(rep.Findings))
		if berr == nil && len(rep.Findings) >= 1 {
			fmt.Printf("    finding evidence=%q version=%q hash=%q\n", rep.Findings[0].Evidence, rep.Findings[0].Version, rep.Findings[0].ArtifactHash)
		}
	}

	// Invariant name independence.
	invIn := `{"artifact":` + artifact + `,"rules":` + rules + `,"invariants":{"Inv":true,"inv":false," inv ":true}}`
	_, _, inv2, _, err := ParseAuditInput([]byte(invIn))
	fmt.Printf("[invariants] err=%v map=%+v (want 3 distinct keys)\n", err, inv2)

	// Escaped status still formal.
	esc := mk(`{"artifactHash":"` + hash + `","ruleId":"r1","version":"1.0.0","status":"发现缺陷","note":"ce x"}`)
	_, _, _, checks3, err := ParseAuditInput([]byte(esc))
	fmt.Printf("[escaped status] err=%v checks=%+v\n", err, checks3)

	// Duplicate inside extension object still rejected.
	dup := mk(`{"artifactHash":"` + hash + `","ruleId":"r1","version":"1.0.0","status":"通过","ext":{"a":1,"a":2}}`)
	_, _, _, _, err = ParseAuditInput([]byte(dup))
	fmt.Printf("[dup in extension] err=%v\n", err)
}

